/**
 * Autogenerated by Postman CLI (postman mock generate)
 * Manually fixed during dogfooding: realistic distinct orders, real id
 * lookup on GET /api/orders/:id, and request-body echo on POST /api/orders.
 */
const http = require('http');
const PORT = process.env.PORT || 5003;

// Seed data — distinct orders (was: two identical objects with the same id).
const orders = [
  {
    id: 'o1',
    userId: 'demo-user',
    items: [
      { productId: 'p1', name: 'Wireless Noise-Cancelling Headphones', price: 149.99, quantity: 1 },
      { productId: 'p4', name: 'Memory Foam Throw Pillow', price: 24.99, quantity: 1 }
    ],
    total: 174.98,
    status: 'confirmed',
    createdAt: '2026-09-22T21:17:21.304Z'
  },
  {
    id: 'o2',
    userId: 'postman-cli-order-test',
    items: [
      { productId: 'p1', name: 'Wireless Noise-Cancelling Headphones', price: 149.99, quantity: 2 },
      { productId: 'p3', name: 'Ceramic Pour-Over Coffee Set', price: 39.5, quantity: 1 }
    ],
    total: 339.48,
    status: 'shipped',
    createdAt: '2026-09-22T22:49:02.600Z'
  },
  {
    id: 'o3',
    userId: 'postman-cli-test-user',
    items: [
      { productId: 'p1', name: 'Wireless Noise-Cancelling Headphones', price: 149.99, quantity: 5 }
    ],
    total: 749.95,
    status: 'delivered',
    createdAt: '2026-09-22T22:51:00.443Z'
  }
];

// Orders created via POST get appended here too, so a GET right after a
// POST in the same run resolves by id like it would against a real backend.
let nextOrderNumber = orders.length + 1;

function readJsonBody(req, callback) {
  let raw = '';
  req.on('data', (chunk) => { raw += chunk; });
  req.on('end', () => {
    if (!raw) return callback(null, {});
    try {
      callback(null, JSON.parse(raw));
    } catch (err) {
      callback(err, null);
    }
  });
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url || '', 'http://localhost');
  const pathname = url.pathname;

  // Allow a browser (e.g. the web-app frontend) to call this mock cross-origin —
  // Postman's deployed mock servers don't add these by default.
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PUT,DELETE,OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type,x-user-id,x-mock-response-code,x-mock-scenario,x-api-key');
  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    return res.end();
  }

  // @endpoint GET /health
  if (req.method === 'GET' && pathname === '/health') {
    res.writeHead(200, {"Content-Type":"application/json"});
    return res.end(JSON.stringify({"status":"ok","service":"order-service"}));
  }

  // @endpoint GET /api/orders
  if (req.method === 'GET' && pathname === '/api/orders') {
    res.writeHead(200, {"Content-Type":"application/json"});
    return res.end(JSON.stringify(orders));
  }

  // @endpoint POST /api/orders
  if (req.method === 'POST' && pathname === '/api/orders') {
    const requestedStatusCode = req.headers['x-mock-response-code'];

    // "Validation failed: userId is missing/empty, or items is missing/empty." — when x-mock-response-code: 400
    if (requestedStatusCode === '400') {
      res.writeHead(400, {"Content-Type":"application/json"});
      return res.end(JSON.stringify({"error":"items is required and must be a non-empty array"}));
    }

    return readJsonBody(req, (err, body) => {
      if (err) {
        res.writeHead(400, {"Content-Type":"application/json"});
        return res.end(JSON.stringify({"error":"Malformed JSON body"}));
      }

      // "Order created." — echoes back the submitted userId/items/total
      // instead of a fixed canned response regardless of input.
      const newOrder = {
        id: 'o' + (nextOrderNumber++),
        userId: body.userId,
        items: body.items,
        total: body.total,
        status: 'confirmed',
        createdAt: new Date().toISOString()
      };
      orders.unshift(newOrder);

      res.writeHead(201, {"Content-Type":"application/json"});
      return res.end(JSON.stringify(newOrder));
    });
  }

  // @endpoint GET /api/orders/:id
  if (req.method === 'GET' && /^\/api\/orders\/([^/]+)$/.test(pathname)) {
    const requestedStatusCode = req.headers['x-mock-response-code'];

    // "No order exists with the given id." — explicit override still works,
    // but it is no longer the only way to get a 404 (see the real lookup below).
    if (requestedStatusCode === '404') {
      res.writeHead(404, {"Content-Type":"application/json"});
      return res.end(JSON.stringify({"error":"Order not found"}));
    }

    const id = pathname.match(/^\/api\/orders\/([^/]+)$/)[1];
    const order = orders.find((o) => o.id === id);

    if (!order) {
      res.writeHead(404, {"Content-Type":"application/json"});
      return res.end(JSON.stringify({"error":"Order not found"}));
    }

    res.writeHead(200, {"Content-Type":"application/json"});
    return res.end(JSON.stringify(order));
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Endpoint not defined' }));
});

server.listen(PORT);
